public class AsdpServiceSession {

    /**
     * 下线ASDP时效
     */
    public static final String SESSION_ATTR_OFFLINE_ASDP_SHIP_AND_ARRIVAL_TIME = "offlineAsdpShipAndArrivalTime";

    /**
     * 下线ASDP商品详情的时效
     */
    public static final String SESSION_ATTR_OFFLINE_ASDP_DETAIL_SHIP_AND_ARRIVAL_TIME = "offlineAsdpDetailShipAndArrivalTime";

    public static final String SESSION_ATTR_OFFLINE_ASDP_NEED_CALCULATE_ADP_SIGN_TIME = "needCalculateAdpSignTime";

    private static final ThreadLocal<AsdpServiceSession> sessionThreadLocal = new ThreadLocal<>();

    public static AsdpServiceSession getSession() {
        return sessionThreadLocal.get();
    }

    public static AsdpServiceSession initSession() {
        if (null == sessionThreadLocal.get()) {
            sessionThreadLocal.set(new AsdpServiceSession());
        }
        return sessionThreadLocal.get();
    }

    public static void destroySession() {
        if (null != sessionThreadLocal.get()) {
            sessionThreadLocal.set(null);
        }
    }

    /**
     * 会话属性
     */
    private final Map<String, Object> contextMap = new HashMap<>();

    public void putAttribute(String name, Object value) {
        contextMap.put(name, value);
    }

    public Object getAttribute(String name) {
        return contextMap.get(name);
    }

    public String getAttributeStr(String name) {
        return Optional.ofNullable(contextMap.get(name))
            .map(String::valueOf)
            .orElse(null);
    }

    public <T> T getAttribute(String name, Class<T> klass) {
        Object obj = contextMap.get(name);
        if (Objects.isNull(obj)) {
            return null;
        }
        if (klass.isInstance(obj)) {
            return klass.cast(obj);
        }
        throw new AsdpException(
            AsdpErrorCodeEnum.ASDP_SYS_ERROR_REPLAY_OVER_TIMES.getAsdpCode(),
            "上下文类型错误：key=" + name + ",expect=" + klass.getName());
    }

    public void removeAttribute(String name) {
        contextMap.remove(name);
    }

    public void setOfflineAsdpShipAndArrivalTime(boolean offlineShipAndArrivalTime) {
        putAttribute(SESSION_ATTR_OFFLINE_ASDP_SHIP_AND_ARRIVAL_TIME, offlineShipAndArrivalTime);
    }

    public void setOfflineAsdpDetailShipAndArrivalTime(boolean offlineDetailShipAndArrivalTime) {
        putAttribute(SESSION_ATTR_OFFLINE_ASDP_DETAIL_SHIP_AND_ARRIVAL_TIME, offlineDetailShipAndArrivalTime);
    }



    /**
     * 是否下线ASDP时效
     *
     * @return true-下线/false-不下线
     */
    public static boolean offlineAsdpShipAndArrivalTime() {
        AsdpServiceSession session = getSession();
        if (Objects.isNull(session)) {
            return false;
        }
        Boolean offlineShipAndArrivalTime = session.getAttribute(
            SESSION_ATTR_OFFLINE_ASDP_SHIP_AND_ARRIVAL_TIME, Boolean.class);
        return Boolean.TRUE.equals(offlineShipAndArrivalTime);
    }

    /**
     * 是否下线ASDP时效
     *
     * @return true-下线/false-不下线
     */
    public static boolean offlineAsdpDetailShipAndArrivalTime() {
        AsdpServiceSession session = getSession();
        if (Objects.isNull(session)) {
            return false;
        }
        Boolean offlineShipAndArrivalTime = session.getAttribute(
                SESSION_ATTR_OFFLINE_ASDP_DETAIL_SHIP_AND_ARRIVAL_TIME, Boolean.class);
        return Boolean.TRUE.equals(offlineShipAndArrivalTime);
    }

    public void setAsdpNeedCalculateAdpSignTime(boolean needCalculateAdpSignTime) {
        putAttribute(SESSION_ATTR_OFFLINE_ASDP_NEED_CALCULATE_ADP_SIGN_TIME, needCalculateAdpSignTime);
    }

    /**
     * ASDP是否触发了ADP到货时效计算
     *
     * @return true-触发/false-未触发
     */
    public static boolean needCalculateAdpSignTime() {
        AsdpServiceSession session = getSession();
        if (Objects.isNull(session)) {
            return false;
        }
        Boolean needCalculateAdpSignTime = session.getAttribute(
            SESSION_ATTR_OFFLINE_ASDP_NEED_CALCULATE_ADP_SIGN_TIME, Boolean.class);
        return Boolean.TRUE.equals(needCalculateAdpSignTime);
    }
}
